private bool DeleteMultiData()
{
    FAM_Device objDevice = new FAM_Device();
    objDevice.BeginTransaction();
    objDevice.DeletedUser = UserSession.Username;

    string strActionLog = "";
    for (int i = dtbData.Rows.Count - 1; i >= 0; i--)
    {
        DataRow drw = dtbData.Rows[i];
        if (Convert.ToBoolean(drw["IsSelected"]))
        {
            objDevice.DeviceID = Convert.ToInt64(drw[FAM_Device.C_DeviceID]);

            if (!objDevice.Delete())
            {
                MessageManager.Error("Xóa thông tin tài sản thất bại");
                return false;
            }
            else //Xóa hình tài sản
            {
                strActionLog += "Mã tài sản: " + drw[FAM_Device.C_DeviceCode].ToString() + "\r\n";
                dtbData.Rows.RemoveAt(i);
            }
        }
    }

    objDevice.CommitTransaction();
    if (strActionLog != "")
        new SystemObject.SYS_ActionLog().WriteActionLog("Xoá tài sản", strActionLog, SystemObject.ActionLogType.DEL, 2, UserSession.Username);
    return true;
}

