private string BuildDeviceQrContent(DataRow drw)
{
    string deviceCode = GetColumnValue(drw, "DeviceCode");
    string deviceName = GetColumnValue(drw, "DeviceName");
    string roomName = GetColumnValue(drw, "RoomName");
    string usingDate = "";

    if (drw.Table.Columns.Contains("UsingDate") && drw["UsingDate"] != DBNull.Value)
        usingDate = Convert.ToDateTime(drw["UsingDate"]).ToString("dd-MM-yyyy");

    return String.Format(
        "Mã tài sản: {0} | Tên tài sản: {1} | Bộ phận sử dụng: {2} | Ngày đưa vào sử dụng: {3}",
        deviceCode,
        deviceName,
        roomName,
        usingDate);
}

