}

private bool IsRowChecked(DataRow drw)
{
    if (drw == null || !drw.Table.Columns.Contains("IsSelected") || drw["IsSelected"] == DBNull.Value)
        return false;

    return Convert.ToBoolean(drw["IsSelected"]);
}

private List<DataRow> GetCheckedRows()
{
    CommitGridEdit();

    List<DataRow> lstResult = new List<DataRow>();
    for (int i = 0; i < gvData.RowCount; i++)
    {
        int intRowHandle = gvData.GetVisibleRowHandle(i);
        if (!gvData.IsDataRow(intRowHandle))
            continue;

        DataRow drw = gvData.GetDataRow(intRowHandle);
        if (IsRowChecked(drw))
            lstResult.Add(drw);
    }

    return lstResult;
}

private bool HasCheckedRow()
{
    return GetCheckedRows().Count > 0;
}

private void UpdateDeleteButtonState()
{
    bool bolHasPermission = UserSession.HasPermission(PERMISSION_DELETE);
    btnDelete.Enabled = mnuItemDelete.Enabled = HasCheckedRow() && bolHasPermission;
}

private void EnsureIsSelectedColumn()
{
    if (dtbData == null)
        return;

    if (!dtbData.Columns.Contains("IsSelected"))
    {
        dtbData.Columns.Add("IsSelected", typeof(bool));
        foreach (DataRow drw in dtbData.Rows)
            drw["IsSelected"] = false;
    }
}

