private void SetSelectedRowsChecked(bool bolChecked)
{
    CommitGridEdit();
    int[] arrRowHandle = gvData.GetSelectedRows();
    for (int i = 0; i < arrRowHandle.Length; i++)
    {
        DataRow drw = gvData.GetDataRow(arrRowHandle[i]);
        if (drw != null && drw.Table.Columns.Contains("IsSelected"))
